package com.projectseele.world;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
public final class NervGateClosureR52Test {
    private static void check(boolean value,String text){if(!value)throw new AssertionError(text);}
    public static void main(String[]args){var cells=new HashSet<BlockPos>();for(int x=-82;x<82;x++)for(int z=-82;z<82;z++)cells.add(new BlockPos(x,68,z));var boxes=NervGateClosureR52.coalesce(cells);check(boxes.size()==1&&boxes.get(0).equals(new AABB(-82,68,-82,82,69,82)),"Real 26896-cell hatch mask becomes one exact closed rectangle");cells.remove(new BlockPos(0,68,0));boxes=NervGateClosureR52.coalesce(cells);check(!NervAirspaceCoverageR52.covered(new AABB(0,68,0,1,69,1),boxes),"Coalescing cannot fabricate a closed voxel in an explicitly absent cell");check(boxes.stream().mapToDouble(b->b.getXsize()*b.getYsize()*b.getZsize()).sum()==cells.size(),"The exact finite mask retains all and only Root voxels");cells.clear();for(int x=0;x<33;x++)for(int y=0;y<75;y++)cells.add(new BlockPos(x,y,3));check(NervGateClosureR52.coalesce(cells).equals(List.of(new AABB(0,0,3,33,75,4))),"Vertical eight-panel gate retains one exact full-hole admission mask");var leafMask=List.of(new AABB(0,68,0,1,69,1));var steel=new NervRigidMeshSweepR52(new double[]{.2,0,.2,.8,0,.2,.2,0,.8});var independent=new RigidTransform(new Vec3(0,68.5,0),0,0,0,1);var distantBody=new RigidTransform(new Vec3(1000,68.5,0),0,0,0,1);check(!NervGateClosureR52.clearIndependentMeshes(List.of(new NervFlightProofR52.ObstacleMesh(steel,independent)),leafMask),"Original detached steel in the closed plane blocks closure even when its body host is 1000m away");check(NervGateClosureR52.clearIndependentMeshes(List.of(new NervFlightProofR52.ObstacleMesh(steel,distantBody)),leafMask),"Control proves that following the remote body would lose the real in-plane steel");check(!NervGateClosureR52.clearIndependentMeshes(null,leafMask),"Unloaded independent original carrier cannot prove an empty closing plane");System.out.println("PASS R52 exact closed-hole voxel union and independent original carrier admission: 7");}
}
